package com.gameaggregator.ledgerservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity @Table(name="revenue_allocations") public class RevenueAllocation{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID transactionId;@Column(nullable=false)public UUID beneficiaryId;@Column(nullable=false)public String beneficiaryType;@Column(nullable=false,precision=19,scale=6)public BigDecimal amount;protected RevenueAllocation(){}public RevenueAllocation(UUID t,UUID b,String y,BigDecimal a){transactionId=t;beneficiaryId=b;beneficiaryType=y;amount=a;}}